mapper.select:
select t.id tournament_id, t.sport_id, t.tournament_level, t.name_code, t.name tournament_name_cn, t.name_spell tournament_name_en, t.tournament_manager_id, tem1.template_name data_source_weight_name, tem1.template_settle_weight_id data_source_weight_id, tem2.template_name count_down_name, tem2.template_count_dowen_id count_down_id, tem3.template_name gray_area_set_name, tem3.template_gray_area_id gray_area_set_id from standard_sport_tournament t left join ( select re.template_settle_weight_id, re.standard_tournament_id, st.template_name from match_settle_template st left join match_settle_template_relation re on re.template_settle_weight_id = st.id ) tem1 on tem1.standard_tournament_id = t.id left join ( select re.template_count_dowen_id, re.standard_tournament_id, st.template_name from match_settle_template st left join match_settle_template_relation re on re.template_count_dowen_id = st.id ) tem2 on tem2.standard_tournament_id = t.id left join ( select re.template_gray_area_id, re.standard_tournament_id, st.template_name from match_settle_template st left join match_settle_template_relation re on re.template_gray_area_id = st.id ) tem3 on tem3.standard_tournament_id = t.id where 1=1
and t.tournament_level = #{tournamentLevel}
and t.sport_id = #{sportId}
and ( t.name like concat('%',#{tournamentName},'%') or t.name_spell like concat('%',#{tournamentName},'%') )
and tem1.template_name like concat('%',#{dataSourceWeight},'%')
and tem2.template_name like concat('%',#{countDown},'%')
and tem3.template_name like concat('%',#{grayAreaSet},'%')
limit #{start},#{end}

select * from ( select t.id tournament_id, t.sport_id, t.tournament_level, t.name_code, t.name tournament_name_cn, t.name_spell tournament_name_en, t.tournament_manager_id, tem1.template_name data_source_weight_name, tem1.template_settle_weight_id data_source_weight_id, tem2.template_name count_down_name, tem2.template_count_dowen_id count_down_id, tem3.template_name gray_area_set_name, tem3.template_gray_area_id gray_area_set_id from standard_sport_tournament t left join ( select re.template_settle_weight_id, re.standard_tournament_id, st.template_name from match_settle_template st left join match_settle_template_relation re on re.template_settle_weight_id = st.id ) tem1 on tem1.standard_tournament_id = t.id left join ( select re.template_count_dowen_id, re.standard_tournament_id, st.template_name from match_settle_template st left join match_settle_template_relation re on re.template_count_dowen_id = st.id ) tem2 on tem2.standard_tournament_id = t.id left join ( select re.template_gray_area_id, re.standard_tournament_id, st.template_name from match_settle_template st left join match_settle_template_relation re on re.template_gray_area_id = st.id ) tem3 on tem3.standard_tournament_id = t.id where 1=1
and t.tournament_level = #{tournamentLevel}
and t.sport_id = #{sportId}
and ( t.name like concat('%',#{tournamentName},'%') or t.name_spell like concat('%',#{tournamentName},'%') )
and tem1.template_name like concat('%',#{dataSourceWeight},'%')
and tem2.template_name like concat('%',#{countDown},'%')
and tem3.template_name like concat('%',#{grayAreaSet},'%')
) as T where 1=1
AND T.data_source_weight_id is null
AND T.gray_area_set_id is null
AND T.count_down_id is null
limit #{start},#{end}

select t.* from match_settle_template t where tournament_level= -1
and t.sport_id = #{sportId}
and t.template_type = #{type}
and t.template_name like concat('%',#{templateName},'%')

mapper.update:
update
match_settle_template_relation
set template_settle_weight_id=null
where  standard_tournament_id in (
  select id from standard_sport_tournament where sport_id =1 and tournament_level = #{tournamentLevel}
)

update
match_settle_template_relation
set template_settle_weight_id=#{templateId}
where  standard_tournament_id in (
  select id from standard_sport_tournament where sport_id =1 and tournament_level = #{tournamentLevel}
)

